{
  "name": "cmux-opencode-notify",
  "version": "0.1.1",
  "description": "cmux notifications and activity status for OpenCode",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "THIRD_PARTY_NOTICES.md"
  ],
  "keywords": [
    "cmux",
    "opencode",
    "opencode-plugin",
    "notifications",
    "terminal"
  ],
  "author": "Lucas Pevidor",
  "license": "MIT",
  "homepage": "https://github.com/lucaspevidor/cmux-opencode-notify#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lucaspevidor/cmux-opencode-notify.git"
  },
  "bugs": {
    "url": "https://github.com/lucaspevidor/cmux-opencode-notify/issues"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.5",
    "@types/node": "^24.0.0",
    "tsx": "^4.20.0",
    "typescript": "^5.9.0"
  },
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "build": "tsc",
    "clean": "rm -rf dist",
    "test": "node --import tsx --test tests/*.test.ts",
    "typecheck": "tsc --noEmit"
  }
}
